import { forwardRef, Children } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { enforceAIItemProps } from "../ai-utils";

import { AIHeaderProps, AIHeaderTitleProps, AIHeaderActionsProps } from "./ai-header.types";
import { AIHeaderClasses, StyledAIHeader } from "./ai-header.styles";

export const AIHeader = forwardRef<HTMLDivElement, AIHeaderProps>(
  ({ className, children, variant = "default", ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(AIHeaderClasses.root, className);

    return (
      <StyledAIHeader
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAIHeader>
    );
  },
);

AIHeader.displayName = "AI.Header";

export const AIHeaderTitle = forwardRef<HTMLElement, AIHeaderTitleProps>(
  ({ className, children, headingLevel = 3, ...props }, ref) => {
    const Tag = `h${headingLevel}` as React.ElementType;

    const processedChildren = Children.map(children, (child) => {
      if (typeof child === "string") {
        return <span className={AIHeaderClasses.titleText}>{child}</span>;
      }
      return child;
    });

    return (
      <Tag ref={ref} className={clsx(AIHeaderClasses.title, className)} {...props}>
        {processedChildren}
      </Tag>
    );
  },
);

AIHeaderTitle.displayName = "AI.HeaderTitle";

export const AIHeaderActions = forwardRef<HTMLDivElement, AIHeaderActionsProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(AIHeaderClasses.actions, className)} {...props}>
        {enforceAIItemProps(children)}
      </div>
    );
  },
);

AIHeaderActions.displayName = "AI.HeaderActions";
